// Companion test for every WardStock flow that calls GoDaddy api/*.php.
// Reads /share/lucius_secrets.json the same way production flows do
// (core "file in" node — Function nodes cannot require('fs')).
// Debugs constructed URLs. Live-calls only read-only GETs plus empty-JSON
// POSTs that the PHP rejects with 400 BEFORE writing anything.
//
// Token values are never printed — length + last 4 only.

function redactToken(val) {
    const s = String(val == null ? '' : val);
    if (!s) return { present: false, length: 0, last4: '' };
    return { present: true, length: s.length, last4: s.length >= 4 ? s.slice(-4) : s };
}

function snippet(body, limit) {
    limit = limit || 280;
    let text;
    if (body === undefined || body === null) text = '';
    else if (typeof body === 'string') text = body;
    else {
        try { text = JSON.stringify(body); } catch (e) { text = String(body); }
    }
    text = String(text).replace(/\s+/g, ' ').trim();
    if (text.length > limit) return text.slice(0, limit) + '…';
    return text;
}

function redactBodyForDebug(body) {
    if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
    const copy = Object.assign({}, body);
    ['oura_client_secret', 'oura_client_id', 'godaddy_api_sync_token', 'API_SYNC_TOKEN', 'access_token', 'refresh_token'].forEach(k => {
        if (copy[k] !== undefined && copy[k] !== null) copy[k] = redactToken(copy[k]);
    });
    return copy;
}

const filePath = '/share/lucius_secrets.json';
const expectedBase = 'https://aileeward.com/wardstock';

msg.results = [];
msg.api_queue = [];
msg.secrets = {};
msg.inventory = { file: filePath, file_found: false, parse_ok: false };
msg._gapi_awaiting = false;

let secrets = null;
const raw = msg.payload;
const errObj = msg.error;

if (errObj) {
    msg.results.push({
        check: 'Secrets file',
        pass: false,
        detail: 'file-in error reading ' + filePath + ': ' + (errObj.message || JSON.stringify(errObj))
    });
} else if (raw === undefined || raw === null || String(raw).trim() === '') {
    msg.results.push({
        check: 'Secrets file',
        pass: false,
        detail: filePath + ' missing or empty. Node-RED file-in with sendError=false yields an empty payload when the file is not found — confirm the file lives on HA /share (not the add-on\'s own /config).'
    });
} else {
    try {
        secrets = JSON.parse(raw);
        msg.inventory.parse_ok = true;
        msg.inventory.file_found = true;
    } catch (e) {
        msg.inventory.file_found = true;
        msg.results.push({ check: 'Secrets file', pass: false, detail: 'JSON parse failed: ' + e.message });
    }
}

if (secrets && typeof secrets === 'object') {
    const keysPresent = Object.keys(secrets).filter(k => k && k.charAt(0) !== '_');
    const required = ['godaddy_base_url', 'godaddy_api_sync_token'];
    const missing = required.filter(k => !secrets[k] || String(secrets[k]).trim() === '');
    const token = String(secrets.godaddy_api_sync_token || '');
    const tokenRedact = redactToken(token);
    const baseRaw = String(secrets.godaddy_base_url || '').trim();
    const base = baseRaw.replace(/\/+$/, '');

    const urlNotes = [];
    if (!base) urlNotes.push('godaddy_base_url empty');
    if (/emperorschildren\.net/i.test(base)) urlNotes.push('STALE HOST emperorschildren.net — should be aileeward.com');
    if (/\/Wardstock\b/.test(base)) urlNotes.push('path uses /Wardstock (capital W) — live path is lowercase /wardstock');
    if (base && !/^https:\/\//i.test(base)) urlNotes.push('not https');
    if (base && base.toLowerCase() !== expectedBase) {
        urlNotes.push('does not match expected ' + expectedBase + ' (got ' + base + ')');
    }
    const urlOk = urlNotes.length === 0 && !!base;

    msg.results.push({
        check: 'Secrets file',
        pass: missing.length === 0,
        detail: 'found=yes parse=ok keys=[' + keysPresent.join(', ') + ']' + (missing.length ? ' MISSING: ' + missing.join(', ') : '')
    });
    msg.results.push({
        check: 'godaddy_base_url',
        pass: urlOk,
        detail: (base || '(empty)') + (urlNotes.length ? ' — ' + urlNotes.join('; ') : ' (matches expected host/path)')
    });
    msg.results.push({
        check: 'godaddy_api_sync_token',
        pass: !!token,
        detail: token ? ('present length=' + tokenRedact.length + ' last4=' + tokenRedact.last4) : 'missing'
    });

    // Every api/*.php Node-RED is supposed to call (inventory of godaddy/app/api/).
    const apis = [
        {
            name: 'status.php',
            path: '/api/status.php',
            method: 'GET',
            live: true,
            expect: 'HTTP 200 + version_in_sync',
            used_by: 'system_test_flow.json (scheduled flows infer reachability from their own calls)'
        },
        {
            name: 'get_shared_config.php',
            path: '/api/get_shared_config.php',
            method: 'GET',
            live: true,
            expect: 'HTTP 200 + preferred_timezone (oura client id/secret redacted in debug)',
            used_by: 'oura_sync_flow.json, oura_backfill_flow.json, analysis_engine_flow.json'
        },
        {
            name: 'pull_manual_data.php',
            path: '/api/pull_manual_data.php?scope=since_last',
            method: 'GET',
            live: false,
            skip_reason: 'This GET always writes last_ha_pull_at, which would advance the production 15-min pull bookmark. URL constructed only — not called.',
            used_by: 'godaddy_pull_flow.json'
        },
        {
            name: 'oura_push.php',
            path: '/api/oura_push.php',
            method: 'POST',
            live: true,
            probe: 'empty_json',
            expect: 'HTTP 400 malformed_request (token accepted; no daily_log write)',
            used_by: 'oura_sync_flow.json'
        },
        {
            name: 'status_push.php',
            path: '/api/status_push.php',
            method: 'POST',
            live: true,
            probe: 'empty_json',
            expect: 'HTTP 400 malformed_request (token accepted; no system_status_reports write)',
            used_by: 'status_heartbeat_flow.json'
        },
        {
            name: 'weight_push.php',
            path: '/api/weight_push.php',
            method: 'POST',
            live: true,
            probe: 'empty_json',
            expect: 'HTTP 400 malformed_request (token accepted; no weight write)',
            used_by: 'body_comp_import_flow.json'
        },
        {
            name: 'incident_push.php',
            path: '/api/incident_push.php',
            method: 'POST',
            live: true,
            probe: 'empty_json',
            expect: 'HTTP 400 malformed_request (token accepted; no incident write)',
            used_by: 'medical_history_import_flow.json'
        },
        {
            name: 'analysis_push.php',
            path: '/api/analysis_push.php',
            method: 'POST',
            live: true,
            probe: 'empty_json',
            expect: 'HTTP 400 malformed_request (token accepted; no analysis_results write)',
            used_by: 'analysis_engine_flow.json'
        }
    ];

    const constructed = apis.map(a => ({
        name: a.name,
        method: a.method,
        url: base ? (base + a.path) : '(no base url)',
        live_call: !!a.live,
        skip_reason: a.skip_reason || null,
        expect: a.expect || null,
        used_by: a.used_by
    }));

    msg.inventory = {
        file: filePath,
        file_found: true,
        parse_ok: true,
        keys_present: keysPresent,
        godaddy_base_url: base || '(empty)',
        expected_base_url: expectedBase,
        token: tokenRedact,
        apis: constructed
    };

    apis.filter(a => !a.live).forEach(a => {
        msg.results.push({
            check: a.name + ' (URL only)',
            pass: !!base,
            detail: (a.skip_reason || 'skipped') + ' → ' + (base ? base + a.path : '(no base)')
        });
    });

    if (base && token) {
        msg.secrets = { godaddy_base_url: base, godaddy_api_sync_token: token };
        msg.api_queue = apis.filter(a => a.live).map(a => ({
            name: a.name,
            method: a.method,
            url: base + a.path,
            probe: a.probe || null,
            expect: a.expect
        }));
    } else {
        msg.results.push({ check: 'Live API calls', pass: false, detail: 'skipped — missing godaddy_base_url or godaddy_api_sync_token' });
    }
}

let inventoryMsg = null;
try {
    inventoryMsg = { payload: JSON.stringify(msg.inventory, null, 2) };
} catch (e) {
    inventoryMsg = { payload: 'inventory stringify failed: ' + e.message };
}
return [msg, inventoryMsg];

// Records the previous HTTP result (if any), then either prepares the
// next queued API call or builds the final summary.
function redactToken(val) {
    const s = String(val == null ? '' : val);
    if (!s) return { present: false, length: 0, last4: '' };
    return { present: true, length: s.length, last4: s.length >= 4 ? s.slice(-4) : s };
}

function snippet(body, limit) {
    limit = limit || 280;
    let text;
    if (body === undefined || body === null) text = '';
    else if (typeof body === 'string') text = body;
    else {
        try { text = JSON.stringify(body); } catch (e) { text = String(body); }
    }
    text = String(text).replace(/\s+/g, ' ').trim();
    if (text.length > limit) return text.slice(0, limit) + '…';
    return text;
}

function redactBodyForDebug(body) {
    if (!body || typeof body !== 'object' || Array.isArray(body)) return body;
    const copy = Object.assign({}, body);
    ['oura_client_secret', 'oura_client_id', 'godaddy_api_sync_token', 'API_SYNC_TOKEN', 'access_token', 'refresh_token'].forEach(k => {
        if (copy[k] !== undefined && copy[k] !== null) copy[k] = redactToken(copy[k]);
    });
    return copy;
}

function bodySnippet(payload) {
    let obj = payload;
    if (typeof payload === 'string') {
        const trimmed = payload.trim();
        if (!trimmed) return '(empty body)';
        try { obj = JSON.parse(trimmed); } catch (e) { return snippet(payload); }
    }
    return snippet(redactBodyForDebug(obj));
}

if (msg._gapi_awaiting && msg.current_api) {
    const api = msg.current_api;
    const code = msg.statusCode;
    let pass = false;
    let detail = '';

    if (typeof code !== 'number' || code === 0) {
        pass = false;
        detail = 'no HTTP status — DNS/TLS/network failure reaching ' + api.url;
    } else if (code === 401) {
        pass = false;
        detail = 'HTTP 401 — reached host, token rejected. Check godaddy_api_sync_token matches config.php API_SYNC_TOKEN.';
    } else if (code === 404) {
        pass = false;
        detail = 'HTTP 404 — endpoint not on the server (app/ not uploaded, or base URL path wrong).';
    } else if (api.method === 'GET') {
        const body = msg.payload;
        if (api.name === 'status.php') {
            pass = (code === 200 && body && body.version_in_sync !== undefined);
            detail = pass
                ? ('HTTP 200 app_version=' + body.app_version + (body.version_in_sync ? ' schema in sync' : ' SCHEMA OUT OF SYNC'))
                : ('HTTP ' + code + ' unexpected for GET status.php — ' + bodySnippet(body));
        } else if (api.name === 'get_shared_config.php') {
            pass = (code === 200 && body && (body.preferred_timezone || body.oura_client_id));
            detail = pass
                ? ('HTTP 200 preferred_timezone=' + (body.preferred_timezone || '(none)') + ' oura_client_id=' + JSON.stringify(redactToken(body.oura_client_id)) + ' oura_client_secret=' + JSON.stringify(redactToken(body.oura_client_secret)))
                : ('HTTP ' + code + ' unexpected for GET get_shared_config.php — ' + bodySnippet(body));
        } else {
            pass = (code === 200);
            detail = 'HTTP ' + code + ' — ' + bodySnippet(body);
        }
    } else {
        // Empty-JSON POST probe: 400 means auth passed and PHP refused to write.
        pass = (code === 400);
        detail = pass
            ? ('HTTP 400 as expected (auth accepted, no write) — ' + bodySnippet(msg.payload))
            : ('HTTP ' + code + ' (wanted 400 malformed_request so nothing is written) — ' + bodySnippet(msg.payload));
    }

    msg.results.push({
        check: api.method + ' ' + api.name,
        pass: pass,
        detail: detail + ' url=' + api.url
    });

    msg._gapi_awaiting = false;
    msg.current_api = null;
}

if (msg.api_queue && msg.api_queue.length) {
    const next = msg.api_queue.shift();
    msg.current_api = next;
    msg.url = next.url;
    msg.method = next.method;
    msg.headers = { Authorization: 'Bearer ' + msg.secrets.godaddy_api_sync_token };
    if (next.probe === 'empty_json') {
        msg.headers['Content-Type'] = 'application/json';
        msg.payload = '{}';
    } else {
        msg.payload = '';
    }
    msg._gapi_awaiting = true;
    return [msg, null];
}

const lines = (msg.results || []).map(r => (r.pass ? '✅' : '❌') + '  ' + r.check + ' — ' + r.detail);
const failed = (msg.results || []).filter(r => !r.pass).length;
const allPass = (msg.results || []).length > 0 && failed === 0;
msg.payload = (allPass ? '=== ALL CHECKS PASSED ===\n' : '=== ' + failed + ' CHECK(S) FAILED ===\n') + lines.join('\n');
msg.all_pass = allPass;
return [null, msg];
